   47	    /** @return array<int, CandidateAction> */
   48	    private function publishedCapabilityCandidates(PerceptionSnapshot $perception): array
   49	    {
   50	        $resourceNeed = $perception->totalResources() > self::RESOURCE_RESERVE ? 1.0 : 0.2;
   51	        $candidates = [];
   52	
   53	        foreach (AiCapability::cases() as $capability) {
   54	            // A replay scenario bypasses the perception builder, so a capability the scenario
   55	            // predates is absent rather than false; absent means unpublished, same as the builder.
   56	            if (!($perception->availableActions[$capability->value] ?? false)) {
   57	                continue;
   58	            }
   59	
   60	            $type = $capability->actionType();
   61	            $need = $type === AiCandidateActionType::Build
   62	                ? $resourceNeed + $this->buildScarcityBoost($perception, $resourceNeed)
   63	                : $resourceNeed;
   64	
   65	            // SP8: a spy or colony dispatch the host would refuse for slot exhaustion is
   66	            // never offered — the account checks the fleet screen before sending.
   67	            if (($type === AiCandidateActionType::Spy || $type === AiCandidateActionType::Colonize) && $perception->fleetSlotsFree < 1) {
   68	                continue;
   69	            }
   70	
   71	            // CL3: a colony the account cannot develop outranks nothing, so colonise is
   72	            // offered only when the existing production can bring the new body online.
   73	            if ($type === AiCandidateActionType::Colonize && !$perception->colonizeEligible) {
   74	                continue;
   75	            }
   76	
   77	            $candidates[] = app()->makeWith(CandidateAction::class, [
   78	                'type' => $type,
   79	                'reason' => AiCandidateReason::publishedCapability($capability),
   80	                'parameters' => [],
   81	                'features' => $this->features($type, $need, 0, 0, $perception->recoveryFactor),
   82	                'sourceTimestamps' => $perception->sourceTimestamps,
   83	            ]);
   84	        }
   85	
   86	        return $candidates;
   87	    }
